package sumtokens

import "testing"

func TestSumExamples(t *testing.T) {
	for _, tc := range []struct {
		input string
		want  int64
	}{
		{"1,2,3", 6},
		{"-2,+5,0", 3},
		{"0007,-0002", 5},
	} {
		got, err := Sum(tc.input)
		if err != nil || got != tc.want {
			t.Errorf("Sum(%q) = %d, %v; want %d, nil", tc.input, got, err, tc.want)
		}
	}
}

func TestSumRejectsInvalidExamples(t *testing.T) {
	for _, input := range []string{"", "1,,2", " 1", "9223372036854775807,1"} {
		if _, err := Sum(input); err == nil {
			t.Errorf("Sum(%q) should return an error", input)
		}
	}
}

