package sumtokens

import (
	"math/rand"
	"strconv"
	"strings"
	"testing"
)

func TestExternalContractValid(t *testing.T) {
	for _, tc := range []struct {
		input string
		want  int64
	}{
		{"0", 0}, {"-0", 0}, {"+0", 0}, {"+17", 17}, {"-17", -17},
		{"0000000007", 7}, {"-00007,+0002", -5}, {"1,2,3", 6},
		{"9223372036854775807", 9223372036854775807},
		{"-9223372036854775808", -9223372036854775808},
		{"9223372036854775807,-9223372036854775808", -1},
		{"-9223372036854775808,9223372036854775807", -1},
		{"9223372036854775807,-1,1", 9223372036854775807},
	} {
		got, err := Sum(tc.input)
		if err != nil || got != tc.want {
			t.Errorf("Sum(%q) = %d, %v; want %d, nil", tc.input, got, err, tc.want)
		}
	}
}

func TestExternalContractInvalid(t *testing.T) {
	for _, input := range []string{
		"", ",", ",1", "1,", "1,,2", "+", "-", "--1", "++1", "+-1", "-+1",
		" 1", "1 ", "1, 2", "1\t", "1\n", "1\r", "1\x002", "1,\n2",
		"١", "１", "1\u00a0", "0x10", "1_000", "1.0", "1e2", "NaN",
		"9223372036854775808", "-9223372036854775809", "999999999999999999999999999999",
		"9223372036854775807,1", "-9223372036854775808,-1",
		"9223372036854775807,1,-1", "-9223372036854775808,-1,1",
	} {
		if _, err := Sum(input); err == nil {
			t.Errorf("Sum(%q) accepted invalid input or intermediate overflow", input)
		}
	}
}

func TestExternalContractGenerated(t *testing.T) {
	rng := rand.New(rand.NewSource(719))
	for iteration := 0; iteration < 200; iteration++ {
		parts := make([]string, 1+rng.Intn(30))
		var want int64
		for index := range parts {
			n := int64(rng.Intn(2000001) - 1000000)
			parts[index] = strconv.FormatInt(n, 10)
			want += n
		}
		input := strings.Join(parts, ",")
		got, err := Sum(input)
		if err != nil || got != want {
			t.Fatalf("generated Sum(%q) = %d, %v; want %d", input, got, err, want)
		}
	}
}

