package sumtokens

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

// Sum parses strict comma-separated signed decimal integers and sums them.
func Sum(input string) (int64, error) {
	var sum int64
	for i, token := range strings.Split(input, ",") {
		digits := token
		if len(digits) > 0 && (digits[0] == '+' || digits[0] == '-') {
			digits = digits[1:]
		}
		if len(digits) == 0 {
			return 0, fmt.Errorf("token %d: missing digits", i+1)
		}
		for j := 0; j < len(digits); j++ {
			if digits[j] < '0' || digits[j] > '9' {
				return 0, fmt.Errorf("token %d: invalid decimal integer", i+1)
			}
		}
		value, err := strconv.ParseInt(token, 10, 64)
		if err != nil {
			return 0, fmt.Errorf("token %d: %w", i+1, err)
		}
		// Check before adding so a wrapped intermediate sum is never accepted.
		if (value > 0 && sum > math.MaxInt64-value) ||
			(value < 0 && sum < math.MinInt64-value) {
			return 0, fmt.Errorf("token %d: sum overflows int64", i+1)
		}
		sum += value
	}
	return sum, nil
}

